function getPyqsForPlace(placeName) {
	const query = placeName.trim().toLowerCase();
	return UPSC_PYQ_DATABASE.filter((q) => q.associatedCoordinates.some((coord) => coord.placeName.toLowerCase().includes(query) || query.includes(coord.placeName.toLowerCase())) || q.questionText.toLowerCase().includes(query) || q.detailedExplanation.toLowerCase().includes(query));
}
