function searchMainsAnswers(query) {
	const q = query.trim().toLowerCase();
	if (!q) return MAINS_MODEL_ANSWERS;
	return MAINS_MODEL_ANSWERS.filter((a) => a.question.toLowerCase().includes(q) || a.topicTheme.toLowerCase().includes(q) || a.syllabusKeywords.some((k) => k.toLowerCase().includes(q)) || a.introduction.toLowerCase().includes(q));
}
